public class NearestNeighbourClassifierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        double[][] train = {{1, 1}, {2, 1}, {4, 5}, {5, 4}, {1, 4}, {0, 0}};
        String[] labels = {"A", "A", "B", "B", "C", "A"};

        try {
            check("distance({0,0}, {3,4})", 5.0,
                    NearestNeighbourClassifier.distance(new double[]{0, 0}, new double[]{3, 4}));
            check("distance in three dimensions", 3.0,
                    NearestNeighbourClassifier.distance(new double[]{1, 2, 2}, new double[]{0, 0, 0}));

            check("classify({1.5, 1}, k = 1)", "A",
                    NearestNeighbourClassifier.classify(train, labels, new double[]{1.5, 1}, 1));
            check("classify({4, 4}, k = 1)", "B",
                    NearestNeighbourClassifier.classify(train, labels, new double[]{4, 4}, 1));
            check("classify({1, 4}, k = 3) outvotes the exact match", "A",
                    NearestNeighbourClassifier.classify(train, labels, new double[]{1, 4}, 3));
            check("classify({2, 3}, k = 2) breaks a tie with the closest", "C",
                    NearestNeighbourClassifier.classify(train, labels, new double[]{2, 3}, 2));
            check("classify({2, 3}, k = 5)", "A",
                    NearestNeighbourClassifier.classify(train, labels, new double[]{2, 3}, 5));
            check("k larger than the training set uses every point", "A",
                    NearestNeighbourClassifier.classify(train, labels, new double[]{2, 3}, 99));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

