/**
 * k-nearest-neighbour classification using Euclidean distance.
 */
public class NearestNeighbourClassifier {

    public static double distance(double[] a, double[] b) {
        double sum = 0.0;
        for (int i = 0; i < a.length; i++) {
            double diff = a[i] - b[i];
            sum += diff * diff;
        }
        return Math.sqrt(sum);
    }

    public static String classify(double[][] train, String[] labels, double[] query, int k) {
        int n = train.length;
        final double[] distances = new double[n];
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            distances[i] = distance(train[i], query);
            order[i] = i;
        }
        java.util.Arrays.sort(order, (p, q) -> {
            int cmp = Double.compare(distances[p], distances[q]);
            return cmp != 0 ? cmp : Integer.compare(p, q);
        });

        int use = Math.min(k, n);
        java.util.Map<String, Integer> counts = new java.util.HashMap<>();
        for (int i = 0; i < use; i++) {
            String label = labels[order[i]];
            counts.put(label, counts.getOrDefault(label, 0) + 1);
        }

        int best = 0;
        for (int count : counts.values()) {
            if (count > best) {
                best = count;
            }
        }
        for (int i = 0; i < use; i++) {
            String label = labels[order[i]];
            if (counts.get(label) == best) {
                return label;
            }
        }
        return null;
    }
}
